  bool isTransPaused=false;
    constructor(
        uint256 _initialAmount,
        uint8 _decimalUnits) public 
    {
        owner=msg.sender; 
		if(_initialAmount<=0){
		    totalSupply = 100000000000000000;    
		    balances[owner]=totalSupply;
		}else{
		    totalSupply = _initialAmount;    
		    balances[owner]=_initialAmount;
		}
		if(_decimalUnits<=0){
